    const w = Math.round(host.getBoundingClientRect().width) || innerWidth
    const h = innerHeight
    if (w === vp.w && h === vp.h) return
    vp.w = w; vp.h = h
    host.style.setProperty("--vw", w + "px")
    host.style.setProperty("--vh", h + "px")
